    claimAction: 'acquire',
    claimOwner: owner,
    claimStage: 'publication',
    leaseMinutes: 30,
    expectedClaimOwner: item.json.claim_owner ?? null,
    expectedClaimExpiresAt: item.json.claim_expires_at ?? null
  } }));

// FIX 2026-07-25 (systemweit gefunden ueber ALLRIS_P9_Mastodon_Publish): ALLRIS_Claim_Lease's
// "Release eigener Claim" matcht per id UND claim_owner - ohne id lief die Freigabe bisher
// stillschweigend ins Leere (0 Zeilen getroffen, kein Fehler), der Claim blieb bis zum
// natuerlichen 30-Minuten-Lease-Ablauf haengen statt sofort freigegeben zu werden.
const vorgangKey = String($json.vorgangKey || '').trim();
const id = $json.id;
if (!vorgangKey) throw new Error('[P8 Claim Release] vorgangKey fehlt.');
if (!id) throw new Error('[P8 Claim Release] id fehlt - Release-Matching in ALLRIS_Claim_Lease braucht id + claim_owner, sonst laeuft die Freigabe stillschweigend ins Leere.');
return [{ json: { id, vorgangKey, claimAction: 'release', claimOwner: `ALLRIS_P8_Partei_Webseite:${$execution.id}` } }];

// Ermittle fehlende Tags (Partei) - vergleicht wpTags (aus "Baue Post-Body") mit den
// bereits existierenden WordPress-Tags von die-partei.net/goslar und trennt in bereits
// vorhandene Tag-IDs und noch anzulegende Tag-Namen. Gleiches Muster wie in
// ALLRIS_P7_WordPress_Publish "Ermittle fehlende Tags".
const current = $('Baue Post-Body').first().json;
const wpTags = Array.isArray(current.wpTags) ? current.wpTags : [];

function norm(v) { return String(v || '').trim().toLowerCase(); }

const rawExisting = $input.all().map(i => i.json);
let existingList = rawExisting;
if (rawExisting.length === 1 && Array.isArray(rawExisting[0])) {
  existingList = rawExisting[0];
}

const existingByName = new Map();
for (const t of existingList) {
  if (t && t.name) existingByName.set(norm(t.name), t.id);
}

const resolvedTagIds = [];
const missingTagNames = [];
const seen = new Set();

for (const rawName of wpTags) {
  const name = String(rawName || '').trim();
  if (!name) continue;
  const n = norm(name);
  if (seen.has(n)) continue;
  seen.add(n);
  if (existingByName.has(n)) {
    resolvedTagIds.push(existingByName.get(n));
  } else {
    missingTagNames.push(name);
  }
}

return [{
  json: {
    ...current,
    resolvedTagIds,
    missingTagNames
  }
}];

// Split fehlende Tags (Partei) - ein Item pro anzulegendem Tag. Sentinel-Item bei 0
// fehlenden Tags, damit die Kette nie mit 0 Items weiterlaeuft.
const current = $input.first().json;
const missing = Array.isArray(current.missingTagNames) ? current.missingTagNames : [];

if (missing.length === 0) {
  return [{ json: { tagName: '', isSentinel: true } }];
}

return missing.map(name => ({ json: { tagName: name, isSentinel: false } }));

// Baue finale Tag-Liste (Partei) - holt den urspruenglichen Beitrags-Kontext von
// "Ermittle fehlende Tags (Partei)" zurueck und ergaenzt die neu angelegten Tag-IDs um
// die bereits vorhandenen. Faengt term_exists-Fehlerantworten ab (Tag wurde zwischen
// Suche und Anlage von woanders bereits erstellt), statt den Tag stillschweigend zu
// verlieren - identisches Muster wie in ALLRIS_P7_WordPress_Publish.
const original = $('Ermittle fehlende Tags (Partei)').first().json;
const resolvedTagIds = Array.isArray(original.resolvedTagIds) ? original.resolvedTagIds : [];

function extractTagId(j) {
  if (!j) return null;
  if (j.id) return j.id;
  if (j.body && j.body.id) return j.body.id;
  if (j.data && j.data.term_id) return j.data.term_id;
  if (j.error && j.error.data && j.error.data.term_id) return j.error.data.term_id;
  return null;
}

const newTagIds = [];
for (const item of $input.all()) {
  const id = extractTagId(item.json || {});
  if (id) newTagIds.push(id);
}

return [{
  json: {
    ...original,
    wordpressTagIds: [...new Set([...resolvedTagIds, ...newTagIds])]
  }
}];
